/* @lc app=leetcode id=2030 lang=kotlin */
class Solution { fun smallestSubsequence(s: String, k: Int, letter: Char, repetition: Int): String = s.foldIndexed(Triple(mutableListOf<Char>(), s.count { it == letter }, IntArray(1))) { i, (st, rem, curRep), c -> (if (c == letter) rem - 1 else rem).let { nRem -> st.also { while (st.isNotEmpty() && st.last() > c && st.size + s.length - i > k && (st.last() != letter || nRem + curRep[0] > repetition)) if (st.removeAt(st.size - 1) == letter) curRep[0]-- }.also { if (st.size < k) if (c == letter) st.add(c).also { curRep[0]++ } else if (k - st.size > repetition - curRep[0]) st.add(c) }.let { Triple(st, nRem, curRep) } } }.first.joinToString("") }